     8→ */
     9→
    10→import * as fs from "node:fs/promises";
    11→import * as path from "node:path";
    12→import { ulid } from "ulid";
    13→import {
    14→  type Plan,
    15→  type PlanInput,
    16→  PlanSchema,
    17→  type PlansFile,
    18→  PlansFileSchema,
    19→} from "../schema/index.js";
    20→import type { KspecContext } from "./yaml.js";
    21→import {
    22→  getAuthor,
    23→  readYamlFile,
    24→  writeYamlFilePreserveFormat,
    25→} from "./yaml.js";
    26→
    27→/**
    28→ * Loaded plan with runtime metadata
    29→ */
    30→export interface LoadedPlan extends Plan {
    31→  _sourceFile?: string;
    32→}
    33→
    34→/**
    35→ * Get the plans file path.
    36→ * AC: @plan-crud ac-1 - stored in project.plans.yaml
    37→ */
    38→export function getPlansFilePath(ctx: KspecContext): string {
    39→  return path.join(ctx.specDir, "project.plans.yaml");
    40→}
    41→
    42→/**
    43→ * Load all plans from the project.
    44→ * AC: @plan-crud ac-7, ac-31 - listing plans
    45→ */
    46→export async function loadPlans(ctx: KspecContext): Promise<LoadedPlan[]> {
    47→  const plansPath = getPlansFilePath(ctx);
    48→
    49→  try {
    50→    const raw = await readYamlFile<unknown>(plansPath);
    51→
    52→    // Validate and parse plans file
    53→    const parsed = PlansFileSchema.safeParse(raw);
    54→    if (!parsed.success) {
    55→      return [];
    56→    }
    57→
    58→    // Add source file metadata to each plan
    59→    return parsed.data.plans.map((plan) => ({
    60→      ...plan,
    61→      _sourceFile: plansPath,
    62→    }));
    63→  } catch {
    64→    // File doesn't exist or parse error
    65→    return [];
    66→  }
    67→}
    68→
    69→/**
    70→ * Find a plan by reference (ULID, short ULID, or slug)
    71→ * AC: @plan-crud ac-8 - get plan by reference
    72→ */
    73→export async function findPlanByRef(
    74→  ctx: KspecContext,
    75→  ref: string,
    76→): Promise<LoadedPlan | undefined> {
    77→  const plans = await loadPlans(ctx);
    78→  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;
    79→
    80→  return plans.find(
    81→    (p) =>
    82→      // Match full ULID
    83→      p._ulid === cleanRef ||
    84→      // Match short ULID (prefix)
    85→      p._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()) ||
    86→      // Match any slug
    87→      p.slugs.includes(cleanRef),
    88→  );
    89→}
    90→
    91→/**
    92→ * Create a new plan from input
    93→ * AC: @plan-crud ac-1, ac-2 - creating plans
    94→ */
    95→export function createPlan(input: PlanInput, author?: string): Plan {
    96→  const now = new Date().toISOString();
    97→
    98→  return {
    99→    _ulid: input._ulid ?? ulid(),
   100→    slugs: input.slugs ?? [],
   101→    title: input.title,
   102→    content: input.content ?? "",
   103→    status: input.status ?? "draft",
   104→    derived_tasks: input.derived_tasks ?? [],
   105→    derived_specs: input.derived_specs ?? [],
   106→    source_path: input.source_path ?? null,
   107→    created_at: input.created_at ?? now,
   108→    approved_at: input.approved_at ?? null,
   109→    completed_at: input.completed_at ?? null,
   110→    notes: input.notes ?? [],
   111→  };
   112→}
   113→
   114→/**
   115→ * Save a single plan (create or update)
   116→ * AC: @plan-crud ac-1, ac-3 - save plan changes
   117→ */
   118→export async function savePlan(
   119→  ctx: KspecContext,
   120→  plan: LoadedPlan,
   121→): Promise<void> {
   122→  const plansPath = getPlansFilePath(ctx);
   123→
   124→  // Ensure directory exists
   125→  const dir = path.dirname(plansPath);
   126→  await fs.mkdir(dir, { recursive: true });
   127→
   128→  // Load existing plans
   129→  const plans = await loadPlans(ctx);
   130→
   131→  // Strip runtime metadata before saving
   132→  const { _sourceFile, ...cleanPlan } = plan;
   133→
   134→  // Update or add
   135→  const existingIndex = plans.findIndex((p) => p._ulid === plan._ulid);
   136→  if (existingIndex >= 0) {
   137→    plans[existingIndex] = cleanPlan as Plan;
   138→  } else {
   139→    plans.push(cleanPlan as Plan);
   140→  }
   141→
   142→  // Save back to file
   143→  const plansFile: PlansFile = {
   144→    kynetic_plans: "1.0",
   145→    plans: plans.map(({ _sourceFile, ...p }) => p as Plan),
   146→  };
   147→
   148→  await writeYamlFilePreserveFormat(plansPath, plansFile);
   149→}
   150→
   151→/**
   152→ * Delete a plan by ULID
   153→ */
   154→export async function deletePlan(
   155→  ctx: KspecContext,
   156→  planUlid: string,
   157→): Promise<boolean> {
   158→  const plansPath = getPlansFilePath(ctx);
   159→
   160→  try {
   161→    const plans = await loadPlans(ctx);
   162→
   163→    // Find plan to delete
   164→    const index = plans.findIndex((p) => p._ulid === planUlid);
   165→    if (index < 0) {
   166→      return false;
   167→    }
   168→
   169→    // Remove plan
   170→    plans.splice(index, 1);
   171→
   172→    // Save back
   173→    const plansFile: PlansFile = {
   174→      kynetic_plans: "1.0",
   175→      plans: plans.map(({ _sourceFile, ...p }) => p as Plan),
   176→    };
   177→
   178→    await writeYamlFilePreserveFormat(plansPath, plansFile);
   179→    return true;
   180→  } catch {
   181→    return false;
   182→  }
   183→}
   184→
   185→/**
   186→ * Filter plans by status
   187→ * AC: @plan-crud ac-7 - list with status filter
   188→ */
   189→export function filterPlansByStatus(
   190→  plans: LoadedPlan[],
   191→  status?: string,
   192→): LoadedPlan[] {
   193→  if (!status) return plans;
   194→  return plans.filter((p) => p.status === status);
   195→}
   196→
   197→/**
   198→ * Get plan statistics
   199→ */
   200→export function getPlanStats(plans: LoadedPlan[]): {
   201→  total: number;
   202→  byStatus: Record<string, number>;
   203→} {
   204→  const byStatus: Record<string, number> = {};
   205→
   206→  for (const plan of plans) {
   207→    byStatus[plan.status] = (byStatus[plan.status] ?? 0) + 1;
   208→  }
   209→
   210→  return {
   211→    total: plans.length,
   212→    byStatus,
   213→  };
   214→}
